import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"59、【涣】 坎下巽上","description":"周易阐真 - 59、【涣】 坎下巽上","frontmatter":{"title":"59、【涣】 坎下巽上","description":"周易阐真 - 59、【涣】 坎下巽上"},"headers":[],"relativePath":"zh/classics/chanzhen/060.md","filePath":"zh/classics/chanzhen/060.md"}'),s={name:"zh/classics/chanzhen/060.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：涣，亨。刚来而不穷，柔得位乎外而上同。王假有庙，王乃在中也。利涉大川，乘木有功也。</p></blockquote><h1 id="_59、【涣】-坎下巽上" tabindex="-1">59、【涣】 坎下巽上 <a class="header-anchor" href="#_59、【涣】-坎下巽上" aria-label="Permalink to “59、【涣】 坎下巽上”">​</a></h1><p>初六：用拯马，壮吉。</p><p>九二：涣奔其机，悔亡。</p><p>六三：涣其躬，无悔。</p><p>六四：涣其群，元吉。涣有丘，匪夷所思。</p><p>九五：涣汗。其大号。涣。王居无咎。</p><p>上九：涣其血，去逖出，无咎。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：风行水上，涣。先王以享于帝立庙。</p><p>涣者，散乱也。上巽风，下坎水，是风行水上也。风性善入，不能入水，水性下流，不受其风，彼此不合，涣之象也。但风虽不能入水，能顺水性而吹；水虽不受其风，能随风吹而扬，又有济涣之象。</p><p>先王有见于此，知人性命秉于天，身体受于亲，虽尊卑贵贱各不相同，善恶邪正各不相等，然其秉受根本则一。以是享帝敬其天，立庙祀其祖，使人人皆知敬天祀祖，不忘其根本耳。根本不忘，本立道生，改恶从善，风移俗易，涣散者合而为一，先王济涣之道大矣哉！修道者能知先王济涣之意，敬天而不违天，报本而不忘本，杀中求生，害里寻恩，则四象可以和，五行可以攒，仍是生初本来面目，何涣之有哉！</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>假，音格。机，音几。逖，音剔。</p><p>涣者，散乱不整之义。卦体下坎一阳藏于二阴之中，阳为阴所陷，上巽一阴入于二阳之下，阳为阴所伤，阴阳不交，性情各别，故谓涣。此阴阳丧乱重整之卦，承上巽卦而来。巽者，渐入真常，以其阴阳散乱，巽进以致济耳。</p><p>人自阴阳散乱，性情迁移，道心昧而人心生，正气伤而邪气盛，如坎中一阳，为阴气所陷，先天藏于后天之中矣。先天既藏，浩气不振，阴气用事，为善不足，为恶有余，不至丧尽天良而不止，如巽之一阴潜生于至阳之下，暗中消阳矣。此涣之所以为涣也。</p><p>然虽已涣，圣人有济焕之道，能使涣者而重整。济涣之道为何道?仍不离巽进之道，所争者顺而消阳，逆则扶阳耳。能逆其巽，于后天中返先天，渐次进步，不急不缓，闲邪存诚，克己复礼，散者能聚，乱者能整，依然当日原物，始涣而终不涣，是涣中而反有亨道矣。</p><p>亨之者，事有险而心不险，外有险而内不险，借柔道而行刚道，以阳气而化阴气，如王假有庙。用诚格神，而神可格，亦如木顺水性，利涉大川，而险可济也。</p><p>夫人之阴阳散涣者，皆由用人心而弃道心，一行一步，俱在险地。果其用道心而去人心，在虎穴中讨命宝，于龙潭里探明珠，巽进于险而通险，逆之顺之，因事制宜，道心常存，人心永灭，五行攒簇，四象和合，何涣之有?但济涣之道，有火候、有工程、有急缓、有止足，毫发之差，千里之失，惟利于正耳。以正而济，急缓得法，进退合时，何不亨，何不利乎?</p><p>初六，在涣之初，道心去之未远，人心生之末盛，若能勇猛拯济，则回头是岸，真宝现前，顺手可得。吉即在于用壮速拯矣。此济涣于涣初者也。</p><p>九二，阳陷阴中，人心用事，已居于涣，宜有悔者。因其刚而得中，人心虽起，道心稳定，如涣奔其机，虽有悔而悔可亡。此处涣而安于涣者也。</p><p>六三，居于险极之地，是行险而有悔者。然有应于阳，顺道心而不顺人心，如涣其躬矣。悔出于有人心，有人心则有身。涣其躬，是无身而无人心。无人心而道心不昧，不致悔而自无悔。此遇涣而能出涣者也。</p><p>六四，柔而守正，炼己持心，虚极静笃，涣散其群阴，以待阳复之时，其吉莫大焉。吉之者，以其能涣散假阴，即能复还真阳。真阳真阴，两而相合，五行攒簇，四象和合，已散者而又聚，已乱者而仍整，大涣而仍大合，如涣有丘，匪夷所思矣。此有涣而归不涣者也。</p><p>九五，阳刚中正，识急缓，明吉凶，去假复真，能以济涣，是以涣汗其大号，涣王居无咎也。人之所以致涣而有咎者，以其误认后天有形之假物，弃先天无形之真实。若能看破后天之假，不为后天所累，如涣其汗矣。既涣其汗而后大号其令，以正除邪，直行济涣之道，则克己可以复礼，复礼可以为仁，心君安静，浑然天理，止于至善一无所咎之地矣。此涣假而能全真者也。</p><p>上九，在涣之终，刚柔混合，是涣其血去逖出也。涣其血者，人心不能伤道心也。去逖出者，道心能以退人心也。道心存，人心去，即人心亦化为道心，金丹凝结，圣胎有象，始而阴阳散涣而有咎者，终而阴阳混合而无咎。此涣终而仍得合者也。</p><p>然则人心生而道心即去，道心生而人心即去。人心足以涣阴阳，道心能以合阴阳。涣中能合，还元返本，复见本来面目，济涣之道尽矣。</p>',26)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
